        }
        private static void Check(bool value,string name,List<string> report){if(!value)throw new Exception(name);report.Add("PASS "+name);}
        internal static int Run(string folder)
        {
            folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);var report=new List<string>();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Desktop desktop=null;Window background=null,document=null;AssistantWindow assistant=null;NativeDockObserver observer=null;IslandMotion morph=null;Action<Window> started=null;
            app.Startup+=async delegate
