                    Motion.TestClientAreaAnimations=true;var profile=Path.Combine(folder,"profile");new SettingsStore(profile).Save(new Preferences{Theme="Dark",ContainedDockApplied=true,Animations=true,ShowTopBar=true,HideDockInApps=false,HideDockInCodex=false,DockAutoHide=false});desktop=new Desktop(profile,true,true);
                    background=new VisualTestBackground{WindowState=WindowState.Normal,Left=0,Top=0,Width=SystemParameters.PrimaryScreenWidth,Height=SystemParameters.PrimaryScreenHeight,Topmost=true,ShowActivated=false,IsHitTestVisible=false};background.SourceInitialized+=delegate{Native.NoActivate(background);};background.Show();
