                    morph.To(366,174);await Task.Delay(100);double intermediate=document.Width;morph.To(190,32);Check(Math.Abs(document.Width-intermediate)<.1,"Retarget de la isla conserva el tamaño actual sin salto",report);
                    for(int i=0;i<18;i++){morph.To(190,32);await Task.Delay(25);}await Task.Delay(150);Check(Math.Abs(document.Width-190)<1&&Math.Abs(document.Height-32)<1&&!morph.Running,"Actualizaciones repetidas terminan en el tamaño exacto y desconectan el resorte",report);
                    morph.To(366,174);await Task.Delay(85);Motion.TestClientAreaAnimations=false;morph.To(126,32);Check(Math.Abs(document.Width-126)<1&&Math.Abs(document.Height-32)<1&&!morph.Running,"Movimiento reducido termina inmediatamente incluso durante una expansión: "+document.Width+" × "+document.Height,report);Motion.TestClientAreaAnimations=true;morph.Dispose();morph=null;document.Close();document=null;
                    desktop.Preferences.HideDockInApps=true;desktop.Preferences.HideDockInCodex=true;desktop.Preferences.DockAutoHide=false;desktop.Preferences.NativeDockAnimations=false;desktop.OpenSettings();var settings=(SettingsWindow)desktop.Settings;settings.SelectPage(2);await Task.Delay(320);var master=ModulesVisual.DescendantsForTest(settings).OfType<CheckBox>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)=="Ocultar automáticamente");Check(master.IsChecked==true,"El interruptor de ocultación refleja también las reglas de apps y Codex",report);master.IsChecked=false;await Task.Delay(320);var apply=ModulesVisual.DescendantsForTest(settings).OfType<Button>().First(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="Aplicar cambios");apply.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(400);Check(!desktop.Preferences.AnyDockAutoHide&&desktop.Preferences.NativeDockAnimations==false,"Aplicar no ocultar desactiva todas las reglas y conserva la preferencia de cierre nativo",report);settings=(SettingsWindow)desktop.Settings;settings.SelectPage(2);await Task.Delay(320);await Program.CaptureOwnWindow(settings,Path.Combine(folder,"dock-settings.png"));settings.Close();
                    var proxy=new Window{Title="MacOS · Destino de prueba",Width=220,Height=120,ShowActivated=false,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize};document=proxy;proxy.SourceInitialized+=delegate{Native.NoActivate(proxy);};proxy.Show();proxy.SetValue(PanelMotion.DockKey,desktop.Preferences.Pins[0].Key);var expected=ModulesVisual.DescendantsForTest(desktop.Dock).OfType<Border>().First(b=>(b.Tag as string)==desktop.Preferences.Pins[0].Key);var center=expected.PointToScreen(new Point(expected.ActualWidth/2,expected.ActualHeight/2));Check((PanelMotion.DockDestination(proxy).Value-center).Length<2,"El destino coincide con el icono de la aplicación y no con el centro genérico",report);proxy.Close();document=null;
                    assistant=new AssistantWindow(desktop,null){ShowActivated=false,IsHitTestVisible=false};assistant.SourceInitialized+=delegate{Native.NoActivate(assistant);};assistant.ShowInput();await Task.Delay(400);await Program.CaptureOwnWindow(assistant,Path.Combine(folder,"assistant-ready.png"));
                    var gemini=new GeminiFixture();assistant.Gemini=gemini;var question=assistant.Execute("¿Por qué el cielo es azul?");Check(gemini.Calls==1&&gemini.Question=="¿Por qué el cielo es azul?"&&desktop.AssistantMode==AssistantStage.Working,"Una pregunta libre llega al proveedor Gemini y muestra trabajo real",report);
                    await assistant.Execute("otra consulta");Check(gemini.Calls==1,"Enviar repetidamente no duplica la consulta en curso",report);
                    assistant.StopAllVoice();Check(gemini.Token.IsCancellationRequested,"Detener cancela el envío/espera de Gemini",report);gemini.Reply.SetResult("Respuesta tardía que no debe aparecer.");await question;Check(desktop.AssistantMode==AssistantStage.Hidden&&!desktop.AssistantSpeaking&&!ModulesVisual.DescendantsForTest(assistant).OfType<TextBlock>().Any(t=>t.Text.Contains("Respuesta tardía")),"Una respuesta tardía cancelada no reaparece ni activa voz o isla",report);
                    gemini=new GeminiFixture();assistant.Gemini=gemini;question=assistant.Execute("Gemini explicame la gravedad");gemini.Reply.SetResult("La gravedad atrae los cuerpos con masa.");await question;Check(gemini.Question=="explicame la gravedad"&&ModulesVisual.DescendantsForTest(assistant).OfType<TextBlock>().Any(t=>t.Text=="La gravedad atrae los cuerpos con masa."),"Gemini con pregunta muestra exactamente la respuesta del proveedor",report);await Program.CaptureOwnWindow(assistant,Path.Combine(folder,"assistant-answer.png"));
                    gemini=new GeminiFixture();assistant.Gemini=gemini;await assistant.Execute("Escribí hola");Check(gemini.Calls==0,"Una orden de escritura sin destino no se transforma en consulta ni se ejecuta sin confirmar",report);assistant.Close();assistant=null;
                    Check(GeminiBrowser.GeminiAddress("https://gemini.google.com/app/123")&&!GeminiBrowser.GeminiAddress("https://gemini.google.com.ejemplo.org/app")&&!GeminiBrowser.GeminiAddress("https://gemini.google.com@ejemplo.org/app")&&!GeminiBrowser.GeminiAddress("http://gemini.google.com/app")&&!GeminiBrowser.GeminiAddress("https://gemini.google.com:8443/app"),"Destino Gemini valida esquema, host, puerto, ruta y ausencia de credenciales",report);
                    Check(GeminiBrowser.AnswerPart("Menú\nGemini ha dicho\nUna respuesta.\nGemini puede cometer errores")=="Una respuesta."&&GeminiBrowser.AnswerPart("No hay respuesta") == "","El lector no presenta menús como respuesta ni inventa contenido ausente",report);
                    document=Document();document.Show();await Task.Delay(300);var entry=Entry(document);int previews=0;Point target=new Point();started=delegate(Window view){previews++;target=PanelMotion.DockDestination(view).Value;};WindowCloseTransition.PreviewStarted+=started;
                    bool enabled=true;observer=new NativeDockObserver(app.Dispatcher,()=>enabled,()=>Native.Matches(entry)?new List<WindowEntry>{entry}:new List<WindowEntry>(),true,()=>entry.Handle);await observer.Sample();Check(observer.CachedImages==1,"Observador conserva como máximo una captura de la ventana activa",report);
                    document.Close();document=null;await Task.Delay(850);Check(previews==1&&GenieTransition.ActiveCount==0,"Cerrar con la X nativa equivalente (WM_CLOSE) genera una sola transición y libera la superficie",report);observer.Dispose();observer=null;
                    document=Document();document.Show();await Task.Delay(200);entry=Entry(document);previews=0;observer=new NativeDockObserver(app.Dispatcher,()=>true,()=>Native.Matches(entry)?new List<WindowEntry>{entry}:new List<WindowEntry>(),true,()=>IntPtr.Zero);await observer.Sample();document.WindowState=WindowState.Minimized;await Task.Delay(1500);Check(previews==1&&Native.Matches(entry)&&Native.IsIconic(entry.Handle),"Minimizar desde Windows usa tarjeta si no hay captura y conserva la aplicación; vistas="+previews+" vigente="+Native.Matches(entry)+" mínima="+Native.IsIconic(entry.Handle)+" eventos="+String.Join(";",observer.Trace),report);observer.Dispose();observer=null;document.Close();document=null;
                    document=Document();document.Show();await Task.Delay(200);entry=Entry(document);previews=0;observer=new NativeDockObserver(app.Dispatcher,()=>true,()=>Native.Matches(entry)?new List<WindowEntry>{entry}:new List<WindowEntry>(),true,()=>IntPtr.Zero);await observer.Sample();System.ComponentModel.CancelEventHandler cancel=delegate(object s,System.ComponentModel.CancelEventArgs e){e.Cancel=true;};document.Closing+=cancel;Native.RequestClose(entry);await Task.Delay(550);Check(previews==0&&document.IsVisible,"Una aplicación que cancela el cierre no genera una despedida falsa",report);document.Closing-=cancel;observer.Dispose();observer=null;document.Close();document=null;
                    entry=null;previews=0;observer=new NativeDockObserver(app.Dispatcher,()=>true,()=>entry==null?new List<WindowEntry>():new List<WindowEntry>{entry},true,()=>IntPtr.Zero);await observer.Sample();document=Document();document.Show();entry=Entry(document);await observer.Sample();await Task.Delay(850);Check(previews==1&&document.IsVisible&&GenieTransition.ActiveCount==0,"Una ventana nueva sale del Dock sin cerrar ni modificar su ventana nativa",report);observer.Dispose();observer=null;document.Close();document=null;
                    WindowCloseTransition.PreviewStarted-=started;started=null;
                    var card=WindowCloseTransition.FallbackCard(new WindowEntry{Title="Documento de demostración",Executable=typeof(PolishVisual).Assembly.Location});foreach(var goal in new[]{new Point(390,610),new Point(0,160),new Point(680,160)})
                    {
                        var surface=new GenieSurface(card,new Rect(90,50,360,220),goal,22,700,640);surface.SetValue(GenieSurface.ProgressProperty,.48);Check(surface.TopWidth>surface.TailWidth*20&&(surface.Tail-goal).Length<.001,"Cola de la malla llega al destino antes de absorber el cuerpo: "+goal,report);
                        if(goal.Y==610){document=new Window{Title="MacOS · Malla de demostración",Width=700,Height=640,Left=70,Top=30,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,Content=surface,ShowActivated=false,ShowInTaskbar=false,Topmost=true,IsHitTestVisible=false};document.SourceInitialized+=delegate{Native.NoActivate(document);};document.Show();await Task.Delay(220);await Program.CaptureOwnWindow(document,Path.Combine(folder,"dock-funnel.png"));document.Close();document=null;}
                        surface.SetValue(GenieSurface.ProgressProperty,1.0);Check((surface.Tail-goal).Length<.001&&surface.TopWidth==0&&surface.TailWidth==0,"La malla se absorbe completamente sin rectángulo residual",report);
                    }
                    report.Add("INFO Gemini/Chrome real no automatizado: el control de Windows detuvo esa comprobación al no verificar la URL. Motor y micrófono reales, apps protegidas y dos monitores físicos pendientes.");File.WriteAllLines(Path.Combine(folder,"polish-tests.txt"),report);app.Shutdown();
                }
                catch(Exception ex){report.Add("FAIL "+ex);File.WriteAllLines(Path.Combine(folder,"polish-tests.txt"),report);app.Shutdown(1);}
