            app.Exit+=delegate{if(started!=null)WindowCloseTransition.PreviewStarted-=started;if(morph!=null)morph.Dispose();if(observer!=null)observer.Dispose();if(assistant!=null)assistant.Close();if(document!=null&&document.IsVisible)document.Close();if(desktop!=null)desktop.Dispose();if(background!=null)background.Close();Motion.TestClientAreaAnimations=null;};return app.Run();
