        private static WindowEntry Entry(Window window){return new WindowEntry{Handle=new WindowInteropHelper(window).Handle,Title=window.Title,Executable=typeof(PolishVisual).Assembly.Location,ProcessId=(uint)System.Diagnostics.Process.GetCurrentProcess().Id};}
        private static Window Document(){return new Window{Title="Documento de prueba MacOS",Width=420,Height=280,Left=180,Top=140,ShowActivated=false,Content=new Grid{Background=Brushes.White,Children={new TextBlock{Text="Documento de prueba\nConserva los avisos de guardar",FontSize=24,Foreground=Brushes.Navy,Margin=new Thickness(30)}}}};}
